module ring_counter (
    input  wire       clk,
    input  wire       reset,
    output wire [7:0] out
);
    reg [7:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) state <= 8'b0000_0001;
        else       state <= {state[6:0], state[7]};
    end

    assign out = state;
endmodule

module ring_counter (
    input  wire       clk,
    input  wire       reset,
    output reg  [7:0] out
);
    // Direct register-on-port variant: eliminate the intermediate state reg
    // so yosys sees one 8-bit FF cluster instead of state+driver.
    always @(posedge clk or posedge reset) begin
        if (reset) out <= 8'b0000_0001;
        else       out <= {out[6:0], out[7]};
    end
endmodule

module ring_counter (
    input  wire       clk,
    input  wire       reset,
    output wire [7:0] out
);
    // Rotate-left expressed as (state<<1) | (state>>7) — synthesizer usually
    // reduces this to the same 1-bit-shift LUT, but it exercises a different
    // source form than the concat-based reference.
    reg [7:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) state <= 8'h01;
        else       state <= (state << 1) | (state >> 7);
    end

    assign out = state;
endmodule

module ring_counter (
    input  wire       clk,
    input  wire       reset,
    output reg  [7:0] out
);
    // Pointer-decoded variant: store a 3-bit index (~3 FFs instead of 8) and
    // one-hot-decode it combinationally. Trades FFs for a small decoder.
    reg [2:0] idx;

    always @(posedge clk or posedge reset) begin
        if (reset) idx <= 3'd0;
        else       idx <= idx + 3'd1;
    end

    always @* begin
        out = 8'b0000_0001 << idx;
    end
endmodule
